# name: last_minus_first_quartile_yes
# description: Yes-rate on trials in the top quartile of trial_index minus yes-rate in the bottom quartile; the model has no session dynamics (null ~0), so observed above null means people grow more liberal over the session, below means more conservative.
def test_statistic(df):
    t = df["trial_index"].astype(float).values
    r = df["rating"].astype(float).values
    q1, q3 = np.quantile(t, [0.25, 0.75])
    lo, hi = r[t <= q1], r[t > q3]
    if len(lo) == 0 or len(hi) == 0:
        return 0.0
    return float(hi.mean() - lo.mean())

# name: set_mean_rate_sd
# description: Standard deviation across number_sets of each set's overall yes-rate (sets with 9+ responses); observed above null means sets differ in overall liberality more than the model predicts (set-specific broad/narrow construal it misses), below means less.
def test_statistic(df):
    g = df.groupby("number_set")["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 9]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].std())
